bash -lc 'set -eu; root=$PWD; out=$(mktemp -d); trap '"'"'rm -rf -- "$out"'"'"' EXIT; export CARGO_TARGET_DIR="$out/target" CARGO_BUILD_JOBS=4; cargo fmt --all -- --check; python3 -c $'"'"'import hashlib\nimport json\nimport pathlib\nimport subprocess\nimport sys\n\nroot, out = map(pathlib.Path, sys.argv[1:])\nwork = out / \'"'"'fixtures\'"'"'\nwork.mkdir()\narchive = out / \'"'"'abc.7z\'"'"'\nsubprocess.run([\'"'"'curl\'"'"', \'"'"'-fsSL\'"'"', \'"'"'--retry\'"'"', \'"'"'2\'"'"', \'"'"'-o\'"'"', str(archive),\n                \'"'"'https://archive.nyu.edu/bitstream/2451/44309/3/abc_0000_step_v00.7z\'"'"'], check=True)\nwith archive.open(\'"'"'rb\'"'"') as file:\n    assert hashlib.file_digest(file, \'"'"'md5\'"'"').hexdigest() == \'"'"'695388be7a278c7798c8c8ae239772ac\'"'"'\n\ntry:\n    import py7zr\nexcept ImportError:\n    subprocess.run([sys.executable, \'"'"'-m\'"'"', \'"'"'pip\'"'"', \'"'"'install\'"'"', \'"'"'--disable-pip-version-check\'"'"',\n                    \'"'"'--target\'"'"', str(out / \'"'"'py7zr\'"'"'), \'"'"'py7zr\'"'"'], check=True)\n    sys.path.insert(0, str(out / \'"'"'py7zr\'"'"'))\n    import py7zr\n\nrows = json.loads((root / \'"'"'tools/predictor/corpus.json\'"'"').read_text())[\'"'"'rows\'"'"']\nmanifest = {row[\'"'"'import\'"'"'][\'"'"'model\'"'"']: row[\'"'"'import\'"'"'][\'"'"'sha256\'"'"'] for row in rows if \'"'"'import\'"'"' in row}\nselection = []\nwith py7zr.SevenZipFile(archive) as file:\n    members = file.getnames()\n    for model, digest in manifest.items():\n        matches = [member for member in members if member.startswith(model + \'"'"'/\'"'"') and member.lower().endswith((\'"'"'.step\'"'"', \'"'"'.stp\'"'"'))]\n        assert len(matches) == 1, (model, matches)\n        selection.append([model, matches[0]])\n    file.extract(path=work, targets=[member for _, member in selection])\nfor model, member in selection:\n    with (work / member).open(\'"'"'rb\'"'"') as file:\n        assert hashlib.file_digest(file, \'"'"'sha256\'"'"').hexdigest() == manifest[model], model\n(work / \'"'"'selection.json\'"'"').write_text(json.dumps(selection))\narchive.unlink()\nprint(f\'"'"'{len(selection)} STEP fixtures verified\'"'"', flush=True)\n'"'"' "$root" "$out"; cargo build --release --locked -p catallax-cli --example predictor_corpus; cp "$CARGO_TARGET_DIR/release/examples/predictor_corpus" "$out/measure-after"; git cat-file -e 6e4b5f89e1396d314e991b24fd777bac037526dd^{commit} || git fetch --no-tags --depth=1 origin 6e4b5f89e1396d314e991b24fd777bac037526dd; git switch --detach --quiet 6e4b5f89e1396d314e991b24fd777bac037526dd; cargo build --release --locked -p catallax-cli --example predictor_corpus; cp "$CARGO_TARGET_DIR/release/examples/predictor_corpus" "$out/measure-before"; git switch --detach --quiet 85c21262a844e3ee6ae00352f00c983cafdc4fa7; export CORPUS_JOBS=4; python3 -c $'"'"'import concurrent.futures\nimport json\nimport os\nimport pathlib\nimport subprocess\nimport sys\n\nroot, proof = map(pathlib.Path, sys.argv[1:3])\ncorpus = root / \'"'"'tools/predictor/corpus.json\'"'"'\nrows = [row[\'"'"'id\'"'"'] for row in json.loads(corpus.read_text())[\'"'"'rows\'"'"']]\nif sys.argv[3:]:\n    rows = [row for row in rows if row in sys.argv[3:]]\n    assert set(rows) == set(sys.argv[3:]), rows\nthreads = (1, 2, 4, 24)\nfixtures = proof / \'"'"'fixtures\'"'"'\nparts = proof / \'"'"'strict-parts\'"'"'\nparts.mkdir(exist_ok=True)\n\n\ndef measure(job):\n    variant, count, row = job\n    name = f\'"'"'{variant}-{count}-{row}\'"'"'\n    result = parts / (name + \'"'"'.jsonl\'"'"')\n    assert not result.exists(), result\n    command = [str(proof / f\'"'"'measure-{variant}\'"'"'), \'"'"'run\'"'"', \'"'"'--root\'"'"', str(root), \'"'"'--corpus\'"'"', str(corpus),\n               \'"'"'--out\'"'"', str(result), \'"'"'--rows\'"'"', row, \'"'"'--threads\'"'"', str(count), \'"'"'--label\'"'"', variant,\n               \'"'"'--sources\'"'"', str(fixtures), \'"'"'--selection\'"'"', str(fixtures / \'"'"'selection.json\'"'"')]\n    log_path = parts / (name + \'"'"'.log\'"'"')\n    try:\n        with log_path.open(\'"'"'wb\'"'"') as log:\n            subprocess.run(command, cwd=root, stdout=log, stderr=log, check=True, timeout=1200)\n    except subprocess.SubprocessError as error:\n        raise RuntimeError(f\'"'"'{name}: {log_path.read_text()}\'"'"') from error\n    assert result.exists() and len(result.read_text().splitlines()) == 1, (name, log_path.read_text())\n    return variant, result\n\n\njobs = [(variant, count, row) for row in rows for variant, count in\n        ((\'"'"'before\'"'"', 1), *((\'"'"'after\'"'"', count) for count in threads))]\nwith concurrent.futures.ThreadPoolExecutor(max_workers=int(os.environ.get(\'"'"'CORPUS_JOBS\'"'"', \'"'"'2\'"'"'))) as pool:\n    with (proof / \'"'"'strict-before.jsonl\'"'"').open(\'"'"'w\'"'"') as before, (proof / \'"'"'strict-after.jsonl\'"'"').open(\'"'"'w\'"'"') as after:\n        outputs = {\'"'"'before\'"'"': before, \'"'"'after\'"'"': after}\n        tasks = {pool.submit(measure, job): job for job in jobs}\n        try:\n            for done in concurrent.futures.as_completed(tasks):\n                variant, result = done.result()\n                outputs[variant].write(result.read_text())\n                outputs[variant].flush()\n        except BaseException:\n            for task in tasks:\n                task.cancel()\n            raise\nprint(f\'"'"'collected {len(jobs)} corpus results\'"'"', flush=True)\n'"'"' "$root" "$out"; python3 -c $'"'"'import collections\nimport json\nimport pathlib\nimport sys\n\ncorpus, before, after = map(pathlib.Path, sys.argv[1:4])\nrows = {row[\'"'"'id\'"'"'] for row in json.loads(corpus.read_text())[\'"'"'rows\'"'"']}\nthreads = {1, 2, 4, 24}\nexpected = {(row, count) for row in rows for count in threads}\n\n\ndef load(path, expected):\n    answers = {}\n    for line in path.read_text().splitlines():\n        answer = json.loads(line)\n        key = answer.pop(\'"'"'id\'"'"'), answer.pop(\'"'"'threads\'"'"')\n        assert key not in answers, (path, key, \'"'"'duplicate row\'"'"')\n        answer.pop(\'"'"'label\'"'"')\n        answer.pop(\'"'"'repeat\'"'"', None)\n        for part in (\'"'"'build\'"'"', \'"'"'export\'"'"'):\n            if answer[part] is None:\n                continue\n            answer[part].pop(\'"'"'ms\'"'"')\n            answer[part].pop(\'"'"'instructions\'"'"', None)\n        answers[key] = answer\n    assert expected == answers.keys(), (path, \'"'"'missing\'"'"', sorted(expected - answers.keys()), \'"'"'extra\'"'"', sorted(answers.keys() - expected))\n    return answers\n\n\nold = load(before, {(row, 1) for row in rows})\nnew = load(after, expected)\nfor row, count in sorted(expected):\n    original, measured = old[row, 1], new[row, count]\n    differences = [field for field in original if measured[field] != original[field]]\n    assert not differences, ((row, count), differences, original, measured)\ncounts = collections.Counter(\'"'"'no export\'"'"' if answer[\'"'"'export\'"'"'] is None else answer[\'"'"'export\'"'"'][\'"'"'status\'"'"'] for (row, count), answer in old.items() if count == 1)\nprint(f\'"'"'{len(rows)} rows at {sorted(threads)} threads: matching STEP SHA-256, work and refusal details; {dict(counts)}\'"'"')\n'"'"' "$root/tools/predictor/corpus.json" "$out/strict-before.jsonl" "$out/strict-after.jsonl"'
